#!/usr/bin/env python3
from pathlib import Path
import argparse,subprocess
p=argparse.ArgumentParser();p.add_argument('--scratch',type=Path,required=True);a=p.parse_args();a.scratch.mkdir(parents=True,exist_ok=True)
r=Path(__file__).resolve().parents[1];s=(r/'tools/winpe/mt8167-peripheral-update.c').read_text();fn=s[s.index('static DWORD selected_runtime('):s.index('static DWORD installed_gpu_extras(')];locator=s[s.index('static DWORD inf_location_missing('):s.index('/* Opt-in only',s.index('static DWORD inf_location_missing('))]
shim='''#include <assert.h>\ntypedef unsigned DWORD;typedef void* HDEVINFO;typedef struct{int x;} SP_DEVINFO_DATA;\n#define ERROR_NOT_READY 21\n#define ERROR_NOT_FOUND 1168\n#define ERROR_FILE_NOT_FOUND 2\nstatic DWORD identity,inf,selected_inf_locator_unverified,selected_inf_probe_stage,calls;\nstatic void record(unsigned i,unsigned event,DWORD value){(void)i;assert(event==0x255&&value==selected_inf_probe_stage);}\nstatic DWORD selected_identity(unsigned i,HDEVINFO h,SP_DEVINFO_DATA*d,int c){(void)i;(void)h;(void)d;assert(c==1);return identity;}\nstatic DWORD installed_inf(unsigned i,HDEVINFO h,SP_DEVINFO_DATA*d,int c){(void)i;(void)h;(void)d;assert(c==1);calls++;return inf;}\n'''
main='''int main(void){DWORD e,errors[]={0,2,5,13,23,1168,1306,1790};unsigned i,stage;SP_DEVINFO_DATA d;identity=0;for(stage=0;stage<=12;stage++){selected_inf_probe_stage=stage;for(i=0;i<sizeof(errors)/sizeof(errors[0]);i++){inf=errors[i];selected_inf_locator_unverified=inf_location_missing(inf,stage);int optional=(inf==2||inf==1168)&&(stage==2||stage==3||stage==4||stage==5||stage==6||stage==8);assert(selected_runtime(10,0,&d,&e)==(optional?0:inf)&&e==inf);}}inf=2;selected_inf_locator_unverified=0;assert(selected_runtime(10,0,&d,&e)==2);inf=1168;assert(selected_runtime(10,0,&d,&e)==1168);for(i=0;i<sizeof(errors)/sizeof(errors[0]);i++)if(errors[i]!=0){identity=errors[i];calls=0;assert(selected_runtime(10,0,&d,&e)==errors[i]&&!calls&&e==21);}return 0;}'''
f=a.scratch/'selected-inf-gate.c';f.write_text(shim+locator+fn+main);exe=a.scratch/'selected-inf-gate';subprocess.run(['cc','-std=c11','-Wall','-Wextra','-Werror','-fsanitize=address,undefined',str(f),'-o',str(exe)],check=True);subprocess.run([str(exe)],check=True);print('ONLY_EXPLICIT_LOCATOR_STAGE_2_1168_OPTIONAL_CONTEXT_CONTENT_IDENTITY_ACCESS_HASH_ERRORS_FATAL_PASS')
